var n=`0196-escudella-i-carn-dolla`;var t=`world-0196`;var a=`AD`;var s=`southern-europe`;var o=4;var r=154;var l={en:`Escudella i Carn d'Olla`,ua:`Ескуделья і карн д'олья`};var g={en:`A classic dish from Andorra, featuring beef shank, chicken thigh, pork shoulder, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Андорра. Основні складники: яловича гомілка, куряче стегно, свиняча лопатка, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 95 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 95 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:95,i:[[`beef-shank`,550,`g`],[`chicken-thigh`,420,`g`],[`pork-shoulder`,350,`g`],[`water`,2300,`ml`],[`yellow-onion`,170,`g`],[`carrot`,170,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 45 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 45 хвилин до м’якості та готовності.`,t:[`simmering`],m:45,i:[[`potato`,350,`g`],[`white-cabbage`,350,`g`],[`canned-chickpeas`,250,`g`],[`celery-stalk`,130,`g`]]},{en:`Cook the listed ingredients in simmering water for about 11 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 11 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:11,i:[[`vermicelli-pasta`,160,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`parsley`,22,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:n,id:t,country:`AD`,region:s,servings:4,minutes:154,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,s as region,o as servings,n as slug,d as steps,g as text,l as title};